def experiment(inputs):
    import random
    trials = inputs.get('trials', [])
    results = []
    def process_task(depth, current_vals):
        if depth > 3 or len(current_vals) <= 1:
            return current_vals
        # 10% chance of branch failure
        if random.random() < 0.1:
            return None
        mid = len(current_vals) // 2
        left = process_task(depth + 1, current_vals[:mid])
        right = process_task(depth + 1, current_vals[mid:])
        if left is None or right is None:
            return None
        return sorted(left + right)
    for trial in trials:
        results.append(process_task(0, trial))
    return results
